// GEMINI MODEL AUTO-DETECT
// Haalt beschikbare modellen op bij startup
// Kiest automatisch beste flash model
// Nooit meer handmatig aanpassen
// ============================================
let GEMINI_MODEL = 'gemini-2.5-flash'; // postpay default — works on billing-enabled accounts

async function detectBestGeminiModel(apiKey) {
  if (!apiKey) return;
  // Priority: cheapest postpay models first (billing enabled account)
  // gemini-2.0-flash = $0.075/1M tokens — best price/quality for postpay
  const PRIORITY = ['gemini-2.5-flash', 'gemini-2.5-flash-lite', 'gemini-2.0-flash-lite', 'gemini-1.5-flash-001'];
  try {
    const resp = await fetch(
      `https://generativelanguage.googleapis.com/v1beta/models?key=${apiKey}`,
      { headers: { 'Content-Type': 'application/json' } }
    );
    if (!resp.ok) {
      console.warn('⚠️ Could not list Gemini models, using default:', GEMINI_MODEL);
      return;
    }
    const data = await resp.json();
    const available = (data.models || []).map(m => m.name.replace('models/', ''));
    console.log(`📋 Gemini models available: ${available.filter(m=>m.includes('flash')).join(', ')}`);
    // Pick first from priority list that exists
    for (const preferred of PRIORITY) {
      if (available.includes(preferred)) {
        GEMINI_MODEL = preferred;
        console.log(`✅ Gemini model selected: ${GEMINI_MODEL}`);
        return;
      }
    }
    // Fallback: any flash model
    const anyFlash = available.find(m => m.includes('flash') && !m.includes('thinking'));
    if (anyFlash) { GEMINI_MODEL = anyFlash; console.log(`✅ Gemini model fallback: ${GEMINI_MODEL}`); }
  } catch(e) {
    console.warn('⚠️ Gemini detect failed, using default:', GEMINI_MODEL, e.message);
  }
}

// Call Gemini with automatic fallback to a secondary model on overload/quota errors.
// No retry delays — just one shot on primary, one shot on fallback if primary was transient-failed.
// Returns: { ok, status, data, modelUsed, errorMessage }
async function callGeminiWithFallback(apiKey, body, primaryModel, fallbackModel) {
  const FALLBACK = fallbackModel || 'gemini-2.5-flash-lite';
  const primary = primaryModel || GEMINI_MODEL;
  const shouldFallback = (status, errMsg) => {
    if (status === 503 || status === 429 || status === 500) return true;
    const m = (errMsg || '').toLowerCase();
    return m.includes('overload') || m.includes('high demand') || m.includes('unavailable') || m.includes('rate limit') || m.includes('quota');
  };
  const tryModel = async (model) => {
    const resp = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    });
    const data = await resp.json().catch(() => ({}));
    return { ok: resp.ok, status: resp.status, data, modelUsed: model, errorMessage: data?.error?.message || '' };
  };
  const first = await tryModel(primary);
  if (first.ok) return first;
  if (primary !== FALLBACK && shouldFallback(first.status, first.errorMessage)) {
    console.warn(`⚠️ Gemini primary (${primary}) failed with "${first.errorMessage || first.status}" — falling back to ${FALLBACK}`);
    const second = await tryModel(FALLBACK);
    if (second.ok) { console.log(`✅ Gemini fallback (${FALLBACK}) succeeded`); return second; }
    // Return the fallback failure so the caller sees the most recent error
    return second;
  }
  return first;
}

