app.post('/api/setup/verify-admin', async (req, res) => {
const { username, password } = req.body;
if (!pool) return res.status(503).json({ success: false, error: 'DB down' });
try {
const result = await pool.query('SELECT * FROM super_admins WHERE username = $1 AND is_active = TRUE', [username]);
if (result.rows.length === 0) return res.status(401).json({ success: false, error: 'Invalid' });
const valid = await bcrypt.compare(password, result.rows[0].password_hash);
if (!valid) return res.status(401).json({ success: false, error: 'Invalid' });
// Reuse existing token if present — never regenerate unless logout is called.
// This keeps localStorage valid across server restarts and multiple devices.
let sessionToken = result.rows[0].session_token;
if (!sessionToken) {
  sessionToken = crypto.randomBytes(32).toString('hex');
  await pool.query('UPDATE super_admins SET session_token = $1, last_login = NOW() WHERE id = $2', [sessionToken, result.rows[0].id]);
} else {
  await pool.query('UPDATE super_admins SET last_login = NOW() WHERE id = $1', [result.rows[0].id]);
}
res.json({ success: true, admin_id: sessionToken });
} catch (e) { res.status(500).json({ success: false, error: 'Server error' }); }
});
app.post('/api/admin/logout', verifyAdmin, async (req, res) => {
  try {
    await pool.query('UPDATE super_admins SET session_token = NULL WHERE id = $1', [req.admin.id]);
    res.json({ success: true });
  } catch(e) { res.json({ success: true }); }
});
app.post('/api/admin/change-password', verifyAdmin, async (req, res) => {
  const { current_password, new_password } = req.body;
  if (!current_password || !new_password) return res.status(400).json({ success: false, error: 'Both current and new password required' });
  if (new_password.length < 8) return res.status(400).json({ success: false, error: 'New password must be at least 8 characters' });
  try {
    const result = await pool.query('SELECT * FROM super_admins WHERE id = $1', [req.admin.id]);
    if (!result.rows.length) return res.status(404).json({ success: false, error: 'Admin not found' });
    const valid = await bcrypt.compare(current_password, result.rows[0].password_hash);
    if (!valid) return res.status(401).json({ success: false, error: 'Current password is incorrect' });
    const newHash = await bcrypt.hash(new_password, 12);
    await pool.query('UPDATE super_admins SET password_hash = $1 WHERE id = $2', [newHash, req.admin.id]);
    res.json({ success: true, message: 'Password updated successfully' });
  } catch (e) { res.status(500).json({ success: false, error: e.message }); }
});

// ✅ FIX v3: Added activated_until alias + computed is_activated so admin.html renderUsers works correctly
app.get('/api/admin/users', verifyAdmin, async (req, res) => {
try {
const r = await pool.query(`
SELECT
  u.*,
  u.activation_expires AS activated_until,
  CASE WHEN u.activation_expires > NOW() THEN TRUE ELSE FALSE END AS is_activated,
  COUNT(s.id) AS scan_count,
  MAX(s.created_at) AS last_scan_at,
  (SELECT s2.business_url FROM scan_log s2 WHERE s2.user_id = u.id ORDER BY s2.created_at DESC LIMIT 1) AS last_scanned_url,
  (SELECT s3.score FROM scan_log s3 WHERE s3.user_id = u.id ORDER BY s3.created_at DESC LIMIT 1) AS last_scan_score
FROM users u
LEFT JOIN scan_log s ON s.user_id = u.id
GROUP BY u.id
ORDER BY u.created_at DESC
`);
// Classify bot vs human based on user_agent
const classifyUA = (ua) => {
  if (!ua) return { is_bot: true, label: 'Unknown', icon: '❓' };
  const u = ua.toLowerCase();
  const bots = ['bot','crawler','spider','scraper','headless','phantom','selenium','puppeteer','python-requests','curl','wget','java/','go-http','axios/','okhttp','libwww','facebookexternalhit','twitterbot','linkedinbot','slurp','baiduspider','yandexbot'];
  if (bots.some(b => u.includes(b))) return { is_bot: true, label: 'Bot/Crawler', icon: '🤖' };
  if (u.includes('mobile') || u.includes('android') || u.includes('iphone')) return { is_bot: false, label: 'Mobile', icon: '📱' };
  if (u.includes('mozilla') || u.includes('chrome') || u.includes('safari') || u.includes('firefox') || u.includes('edge')) return { is_bot: false, label: 'Browser', icon: '🌐' };
  return { is_bot: true, label: 'Automated', icon: '⚙️' };
};
const users = r.rows.map(u => ({ ...u, _ua: classifyUA(u.user_agent) }));
res.json({ success: true, users });
}
catch (e) { res.json({ success: false, error: e.message }); }
});
