// ══════════════════════════════════════════════════════════════════════
// ══════════════════════════════════════════════════════════════════════
// SITEMAP FETCH — /api/fetch-sitemap?url=
// Fetches a sitemap.xml and returns all page URLs
// ══════════════════════════════════════════════════════════════════════
app.get('/api/fetch-sitemap', async (req, res) => {
  const { url } = req.query;
  if (!url) return res.status(400).json({ error: 'url required' });
  try {
    // Normalize: ensure https, handle www
    let fetchUrl = url;
    if (fetchUrl.startsWith('http://')) fetchUrl = fetchUrl.replace('http://', 'https://');
    const resp = await axios.get(fetchUrl, { 
      timeout: 10000, 
      headers: { 'User-Agent': 'ContentScaleBot/1.0' }, 
      responseType: 'text',
      maxRedirects: 5
    }).catch(async (e) => {
      // Try www variant if non-www fails (or vice versa)
      const alt = fetchUrl.includes('://www.') 
        ? fetchUrl.replace('://www.', '://') 
        : fetchUrl.replace('://', '://www.');
      return axios.get(alt, { timeout: 10000, headers: { 'User-Agent': 'ContentScaleBot/1.0' }, responseType: 'text', maxRedirects: 5 });
    });
    const xml = resp.data;
    const locRegex = /<loc>(.*?)<\/loc>/gi;
    const urls = [], subSitemaps = [];
    let match;
    while ((match = locRegex.exec(xml)) !== null) {
      const u = match[1].trim();
      if (!u) continue;
      if (u.endsWith('.xml')) subSitemaps.push(u); // sitemap index
      else urls.push(u);
    }
    console.log(`[sitemap] ${url} => ${urls.length} URLs, ${subSitemaps.length} sub-sitemaps`);
    // If sitemap index with no direct URLs, auto-fetch best sub-sitemap
    if (urls.length === 0 && subSitemaps.length > 0) {
      // Prefer page-sitemap over post/category sitemaps
      const preferred = subSitemaps.find(u => u.includes('page')) || subSitemaps[0];
      const sub = await axios.get(preferred, { timeout: 10000, headers: { 'User-Agent': 'ContentScaleBot/1.0' }, responseType: 'text' });
      const subXml = sub.data;
      const subRegex = /<loc>(.*?)<\/loc>/gi;
      let sm;
      while ((sm = subRegex.exec(subXml)) !== null) {
        const u = sm[1].trim();
        if (u && !u.endsWith('.xml')) urls.push(u);
      }
      console.log(`[sitemap] auto-fetched sub-sitemap ${subSitemaps[0]} => ${urls.length} URLs`);
    }
    res.json({ success: true, urls, subSitemaps, count: urls.length });
  } catch(e) {
    res.status(500).json({ success: false, error: e.message });
  }
});

// GSC AUTO-FILL — /api/gsc/auto-fill
// Haalt GSC data op voor een specifieke pagina via Service Account
// Vereist: GSC_SERVICE_ACCOUNT_JSON env var in Railway
// ══════════════════════════════════════════════════════════════════════
app.post('/api/gsc/auto-fill', async (req, res) => {
  if (!_gscServiceAccount) {
    return res.status(503).json({
      success: false,
      error: 'GSC_SERVICE_ACCOUNT_JSON niet geconfigureerd in Railway Variables'
    });
  }

  const { pageUrl } = req.body;
  if (!pageUrl) return res.status(400).json({ success: false, error: 'pageUrl required' });

  try {
    const urlObj = new URL(pageUrl);

    // Helper: try a GSC query with a given siteUrl, return rows or throw
    async function tryGscQuery(accessToken, siteUrlToTry, dims, filterPage, startDate, endDate) {
      const body = { startDate, endDate, dimensions: dims,
        dimensionFilterGroups: filterPage ? [{ filters: [{ dimension: 'page', operator: 'equals', expression: pageUrl }] }] : [],
        rowLimit: 20 };
      const r = await fetch(
        `https://www.googleapis.com/webmasters/v3/sites/${encodeURIComponent(siteUrlToTry)}/searchAnalytics/query`,
        { method: 'POST', headers: { Authorization: `Bearer ${accessToken}` }, body: JSON.stringify(body) }
      );
      if (!r.ok) { const e = await r.json(); throw new Error(e.error?.message || r.status); }
      return (await r.json()).rows || [];
    }

    const now = Math.floor(Date.now() / 1000);
    const { createSign } = require('crypto');
    const header = Buffer.from(JSON.stringify({ alg: 'RS256', typ: 'JWT' })).toString('base64url');
    const payload = Buffer.from(JSON.stringify({
      iss: _gscServiceAccount.client_email,
      scope: 'https://www.googleapis.com/auth/webmasters.readonly',
      aud: 'https://oauth2.googleapis.com/token',
      exp: now + 3600,
      iat: now
    })).toString('base64url');

    const sign = createSign('RSA-SHA256');
    sign.update(`${header}.${payload}`);
    const signature = sign.sign(_gscServiceAccount.private_key, 'base64url');
    const jwt = `${header}.${payload}.${signature}`;

    const tokenResp = await axios.post('https://oauth2.googleapis.com/token',
      new URLSearchParams({
        grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer',
        assertion: jwt
      }).toString(),
      { headers: { 'Content-Type': 'application/x-www-form-urlencoded' } }
    );

    const accessToken = tokenResp.data.access_token;
    const endDate = new Date().toISOString().split('T')[0];
    const startDate = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

    // Try multiple site URL formats — GSC properties can be registered differently
    const siteUrlFormats = [
      `https://${urlObj.hostname}/`,
      `http://${urlObj.hostname}/`,
      `sc-domain:${urlObj.hostname.replace(/^www\./, '')}`,
      `https://www.${urlObj.hostname.replace(/^www\./, '')}/`,
    ];

    let pageRows = [], queryRows = [], usedSiteUrl = '';
    for (const fmt of siteUrlFormats) {
      try {
        pageRows = await tryGscQuery(accessToken, fmt, ['page'], true, startDate, endDate);
        queryRows = await tryGscQuery(accessToken, fmt, ['query'], true, startDate, endDate);
        usedSiteUrl = fmt;
        console.log(`[gsc] Using site format: ${fmt}`);
        break;
      } catch(e) {
        console.log(`[gsc] Format ${fmt} failed: ${e.message}`);
      }
    }

    if (!usedSiteUrl) throw new Error('No GSC property found for this site — check that the service account has access');

    let impressions = 0, clicks = 0, ctr = 0, position = 0;
    if (pageRows.length > 0) {
      impressions = Math.round(pageRows[0].impressions || 0);
      clicks = Math.round(pageRows[0].clicks || 0);
      ctr = parseFloat(((pageRows[0].ctr || 0) * 100).toFixed(2));
      position = parseFloat((pageRows[0].position || 0).toFixed(1));
    }

    // Mobile % — query by device dimension
    let mobilePct = null;
    try {
      const mobileRows = await tryGscQuery(accessToken, usedSiteUrl, ['device'], true, startDate, endDate);
      if (mobileRows.length) {
        const total = mobileRows.reduce((a, r) => a + (r.clicks || 0), 0);
        const mRow = mobileRows.find(r => (r.keys[0]||'').toUpperCase() === 'MOBILE');
        if (mRow && total > 0) mobilePct = Math.round((mRow.clicks / total) * 100);
      }
    } catch(e) { /* mobile is optional */ }

    // Sort by impressions descending — highest volume query first
    const sortedByImpr = [...queryRows].sort((a, b) => (b.impressions||0) - (a.impressions||0));
    const topQueries = sortedByImpr.slice(0, 15).map(r => r.keys[0]).join('\n');
    const topKeyword = sortedByImpr[0]?.keys[0] || '';
    const topKeywordImpr = Math.round(sortedByImpr[0]?.impressions || 0);

    console.log(`[gsc] ${pageUrl} => ${impressions} impr ${ctr}% CTR pos ${position} | top kw: "${topKeyword}" (${topKeywordImpr} impr)`);

    res.json({
      success: true,
      data: { impressions, clicks, ctr, position, topQueries, topKeyword, topKeywordImpr,
              mobilePct, queryCount: queryRows.length, dateRange: `${startDate} => ${endDate}` }
    });

  } catch(e) {
    const msg = e.response && e.response.data && e.response.data.error
      ? (e.response.data.error.message || e.response.data.error)
      : e.message;
    console.error('[gsc] error:', msg);
    let hint = '';
    if (msg.includes('403') || msg.includes('Forbidden')) {
      hint = ' — Voeg service account toe aan GSC: seo-audit-tool-service-account@pure-heuristic-473710-t1.iam.gserviceaccount.com';
    }
    res.status(500).json({ success: false, error: msg + hint });
  }
});


