// ── Campaign call: fire VAPI with campaign script ─────────────────────────
app.post('/api/campaigns/:id/call', async (req, res) => {
  const { leadId, clientId } = req.body || {};
  try {
    // Load campaign + lead + client
    const [cmpR, leadR, clR] = await Promise.all([
      pool.query('SELECT * FROM sitemap_campaigns WHERE id=$1', [req.params.id]),
      pool.query('SELECT * FROM campaign_leads WHERE id=$1', [leadId]),
      pool.query('SELECT * FROM campaign_clients WHERE id=$1', [clientId]),
    ]);
    if (!cmpR.rows.length || !leadR.rows.length || !clR.rows.length)
      return res.status(404).json({ error: 'Campaign, lead or client not found' });

    const cmp = cmpR.rows[0], lead = leadR.rows[0], cl = clR.rows[0];

    // Test mode check
    if (cl.is_test && cl.test_calls_used >= cl.test_calls_limit)
      return res.status(403).json({ error: `Test limit reached (${cl.test_calls_limit} calls). Contact Ottmar to upgrade.` });

    const privateKey = cl.vapi_key || process.env.VAPI_PRIVATE_KEY;
    const phoneId    = cl.vapi_phone_id || process.env.VAPI_PHONE_ID;
    if (!privateKey) return res.status(500).json({ error: 'No VAPI key configured' });
    if (!phoneId)    return res.status(500).json({ error: 'No VAPI Phone ID configured' });

    // ── Mobile number check — mobile = manual only ────────────────────────
    if (lead.line_type === 'mobile') {
      return res.status(403).json({ error: 'MOBILE_NUMBER', message: 'This is a mobile number — call manually to comply with TCPA regulations.' });
    }

    // ── Global opt-out check ───────────────────────────────────────────────
    const optoutCheck = await pool.query('SELECT id FROM optout_list WHERE phone=$1', [phone]);
    if (optoutCheck.rows.length > 0) {
      return res.status(403).json({ error: 'OPT_OUT', message: 'This number is on the global opt-out list.' });
    }

    // Timezone / calling hours check
    const tzCheck = checkCallingHours(lead.phone);
    if (!tzCheck.allowed) return res.status(400).json({ error: tzCheck.reason, blocked: true, localTime: tzCheck.localTime });

    let phone = lead.phone.replace(/[\s\-().]/g,'');
    if (!phone.startsWith('+')) phone = '+' + phone;

    // Build disclosure + script based on account type
    const disclosedAs = cmp.disclosure_name || cmp.company_name || 'ContentScale';
    const contactPerson = cmp.contact_person || 'our team';
    const freeOffer = cmp.free_offer ? `, offering a ${cmp.free_offer}` : '';
    const purpose = cmp.call_purpose || 'leads';

    // ContentScale mode vs Client mode
    const isCS = cmp.account_type === 'contentscale';
    const pitch = lead.pitch || (isCS
      ? `I scanned ${lead.domain||'your website'} and noticed it has only ${lead.pages||'a few'} pages — competitors in ${lead.city||'your area'} ranking on Google have 3 to 4 times more content.`
      : `We work in ${lead.city||'your area'}${freeOffer} and wanted to reach out.`);

    const systemPrompt = isCS
      ? `You are an AI assistant calling on behalf of Ottmar Francisca, founder of ContentScale — an SEO content agency in Amsterdam.

ALWAYS start with AI disclosure. Never pretend to be human.
If asked "are you real?" → "I'm an AI, yes — Ottmar is a real person and will follow up personally."
If they say not interested → confirm and end call immediately.

LEAD: ${lead.name||'the business'} | ${lead.domain||''} | ${lead.city||''} | ~${lead.pages||'?'} pages
PITCH: ${pitch}

CALL FLOW:
1. "Hi, just to be transparent — I'm an AI calling on behalf of Ottmar Francisca, founder of ContentScale. Am I speaking with someone from ${lead.name||'the business'}?"
2. If yes: "${pitch} Do you have 60 seconds?"
3. ONE discovery question: "Are you currently getting leads from Google or mostly referrals?"
4. Offer: "I'd love to send a free one-page SEO audit for your site. What's the best email?"
   → GET EMAIL — repeat letter by letter to confirm.
5. Book call: "Ottmar, founder of ContentScale, would love to walk you through it. What day works? And what time — afternoons work well, like 2 or 3pm? And your timezone?"
   → Confirm: "[day], [time], [timezone] — that's [time] Amsterdam time."
6. Best phone: "Is this the best number or is there a better one?"
7. Close: "Perfect! You'll get the audit by email and Ottmar, founder of ContentScale, will confirm your slot. Have a great day!"

Collect: email ✓ | day + time + timezone ✓ | best phone ✓
Keep it under 3 minutes. Warm, never robotic.`

      : `You are an AI assistant calling on behalf of ${disclosedAs}.

ALWAYS start with AI disclosure. Never pretend to be human.
If asked "are you real?" → "I'm an AI assistant, yes — ${contactPerson} will follow up personally."
If they say not interested → apologize and end call immediately.

PURPOSE: ${purpose}
LEAD: ${lead.name||'the contact'} | ${lead.city||''} | audience: ${lead.audience_type||'general'}
PITCH: ${pitch}

CALL FLOW:
1. "Hi, just to be transparent — I'm an AI assistant calling on behalf of ${disclosedAs}. ${pitch} Is this a good moment?"
2. If yes: brief discovery — one question about their situation.
3. ${cmp.free_offer ? `Offer: "We're offering a ${cmp.free_offer} — would that be useful for you?"` : `"Would you be open to a quick conversation with ${contactPerson}?"`}
4. If interested: "What's the best email to send you details?"
   → GET EMAIL — repeat letter by letter to confirm.
5. Book callback: "${contactPerson} can call you back. What day and time works? And your timezone?"
   → Confirm: "[day], [time], [timezone]."
6. Best phone: "Is this the best number?"
7. Close: "Perfect! ${contactPerson} from ${disclosedAs} will be in touch. Have a great day!"

Collect: email ✓ | day + time + timezone ✓ | best phone ✓
Keep it under 3 minutes. Warm and conversational.`;

    const voice = cl.voice || 'nova';
    const assistant = {
      firstMessage: isCS
        ? `Hi, just to be transparent — I'm an AI assistant calling on behalf of Ottmar Francisca, founder of ContentScale. Am I speaking with someone from ${lead.name||'the business'}?`
        : `Hi, just to be transparent — I'm an AI assistant calling on behalf of ${disclosedAs}. Is this ${lead.name||'the right person'}?`,
      model: { provider: 'openai', model: 'gpt-4o', temperature: 0.6, systemPrompt },
      voice: { provider: 'openai', voiceId: voice },
      endCallMessage: 'Thanks for your time. Have a wonderful day!',
      voicemailMessage: isCS
        ? `Hi, this is an AI assistant for Ottmar Francisca, founder of ContentScale. I scanned ${lead.domain||'your website'} and have a free SEO audit ready for you. Email info@contentscale.site or visit contentscale.site. Have a great day!`
        : `Hi, this is an AI assistant for ${disclosedAs}. We wanted to reach out about ${cmp.service||'our services'}. Please call ${contactPerson} back at your convenience. Thank you!`,
      maxDurationSeconds: 240,
      backchannelingEnabled: true,
      endCallFunctionEnabled: true,
    };

    const upstream = await fetch('https://api.vapi.ai/call/phone', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + privateKey },
      body: JSON.stringify({ phoneNumberId: phoneId, customer: { number: phone, name: lead.name||'Lead' }, assistant }),
    });
    const data = await upstream.json();
    if (!upstream.ok) return res.status(upstream.status).json({ error: data.message || JSON.stringify(data).slice(0,200) });

    // Update lead state + call stats
    await pool.query('UPDATE campaign_leads SET call_state=$1, call_id=$2, called_at=NOW() WHERE id=$3',
      ['calling', data.id, leadId]);
    await pool.query('UPDATE campaigns SET calls_made=calls_made+1 WHERE id=$1', [req.params.id]);
    if (cl.is_test) await pool.query('UPDATE campaign_clients SET test_calls_used=test_calls_used+1 WHERE id=$1', [clientId]);

    // Log the call
    await pool.query(`INSERT INTO campaign_call_log (client_id,campaign_id,lead_name,phone,call_id,state)
      VALUES($1,$2,$3,$4,$5,'calling')`,
      [clientId, req.params.id, lead.name, lead.phone, data.id]);

    res.json({ ok: true, callId: data.id, status: data.status });
  } catch(e) {
    console.error('[campaigns/call]', e.message);
    res.status(502).json({ error: e.message });
  }
});

// ── VAPI webhook: update call duration + minutes when call ends ──────────────
app.post('/api/campaigns/webhook', async (req, res) => {
  try {
    const event = req.body;
    const callId = event?.message?.call?.id || event?.call?.id;
    const type   = event?.message?.type || event?.type;

    if (!callId) return res.sendStatus(200);

    // Only process call-ended events
    if (type !== 'end-of-call-report' && type !== 'call-ended') return res.sendStatus(200);

    const call = event?.message?.call || event?.call || {};
    const durationSeconds = call.endedAt && call.startedAt
      ? Math.round((new Date(call.endedAt) - new Date(call.startedAt)) / 1000)
      : (event?.message?.durationSeconds || 0);
    const endedReason = call.endedReason || event?.message?.endedReason || 'unknown';
    const summary     = event?.message?.summary || '';
    const durationMin = Math.ceil(durationSeconds / 60);

    // Find the log entry by call_id
    const logRow = await pool.query(
      'SELECT * FROM campaign_call_log WHERE call_id=$1 LIMIT 1', [callId]
    );
    if (!logRow.rows.length) return res.sendStatus(200);
    const log = logRow.rows[0];

    // Update call log with duration + outcome
    await pool.query(
      `UPDATE campaign_call_log SET state='done', duration_seconds=$1, ended_reason=$2, summary=$3 WHERE call_id=$4`,
      [durationSeconds, endedReason, summary, callId]
    );

    // Update lead state
    await pool.query(
      `UPDATE campaign_leads SET call_state='done' WHERE call_id=$1`,
      [callId]
    );

    // Track minutes per client (only when using Ottmar's VAPI key)
    const cl = await pool.query('SELECT * FROM campaign_clients WHERE id=$1', [log.client_id]);
    if (cl.rows.length && !cl.rows[0].vapi_key) {
      // Using Ottmar's key — track minutes
      await pool.query(
        'UPDATE campaign_clients SET minutes_used=minutes_used+$1 WHERE id=$2',
        [durationMin, log.client_id]
      );
      // Check if over limit
      const updated = await pool.query('SELECT minutes_used, minutes_limit FROM campaign_clients WHERE id=$1', [log.client_id]);
      const { minutes_used, minutes_limit } = updated.rows[0];
      if (minutes_limit > 0 && minutes_used >= minutes_limit) {
        await pool.query('UPDATE campaign_clients SET is_active=FALSE WHERE id=$1', [log.client_id]);
        console.log(`[campaigns/webhook] Client ${log.client_id} blocked — minutes limit reached (${minutes_used}/${minutes_limit})`);
      }
    }

    console.log(`[campaigns/webhook] call ${callId} ended — ${durationSeconds}s (${endedReason}) client ${log.client_id}`);
    res.sendStatus(200);
  } catch(e) {
    console.error('[campaigns/webhook]', e.message);
    res.sendStatus(200);
  }
});

// ── Poll VAPI status for a campaign call and update DB ────────────────────────
app.get('/api/campaigns/call-status/:callId', async (req, res) => {
  const { callId } = req.params;
  const { clientId } = req.query;
  try {
    // Get client's VAPI key
    let privateKey = process.env.VAPI_PRIVATE_KEY;
    if (clientId) {
      const cl = await pool.query('SELECT vapi_key FROM campaign_clients WHERE id=$1', [clientId]);
      if (cl.rows.length && cl.rows[0].vapi_key) privateKey = cl.rows[0].vapi_key;
    }
    const r = await fetch('https://api.vapi.ai/call/' + callId, {
      headers: { 'Authorization': 'Bearer ' + privateKey }
    });
    const data = await r.json();
    const durationSeconds = data.endedAt && data.startedAt
      ? Math.round((new Date(data.endedAt) - new Date(data.startedAt)) / 1000) : null;
    const durationMin = durationSeconds ? Math.ceil(durationSeconds / 60) : 0;

    if (data.status === 'ended' && durationSeconds !== null) {
      // Update log + lead + minutes
      await pool.query(
        `UPDATE campaign_call_log SET state='done', duration_seconds=$1, ended_reason=$2 WHERE call_id=$3`,
        [durationSeconds, data.endedReason||'ended', callId]
      );
      await pool.query(`UPDATE campaign_leads SET call_state='done' WHERE call_id=$1`, [callId]);

      // Track minutes if using Ottmar's key
      const cl = await pool.query('SELECT vapi_key, minutes_limit FROM campaign_clients WHERE id=$1', [clientId]);
      if (cl.rows.length && !cl.rows[0].vapi_key && durationMin > 0) {
        await pool.query('UPDATE campaign_clients SET minutes_used=minutes_used+$1 WHERE id=$2', [durationMin, clientId]);
        const lim = cl.rows[0].minutes_limit;
        const upd = await pool.query('SELECT minutes_used FROM campaign_clients WHERE id=$1', [clientId]);
        if (lim > 0 && upd.rows[0].minutes_used >= lim) {
          await pool.query('UPDATE campaign_clients SET is_active=FALSE WHERE id=$1', [clientId]);
        }
      }
    }
    res.json({ status: data.status, durationSeconds, endedReason: data.endedReason });
  } catch(e) { res.status(502).json({ error: e.message }); }
});

