// GET /api/client-progress — klant haalt eigen voortgang op via session token
app.get('/api/client-progress', async (req, res) => {
  const token = req.headers['x-access-token'];
  if (!token) return res.status(401).json({ success: false, error: 'No token' });
  try {
    const sess = await pool.query(
      `SELECT ac.* FROM access_sessions s
       JOIN access_codes ac ON ac.id=s.code_id
       WHERE s.token=$1 AND s.expires_at>NOW() AND ac.is_active=TRUE`,
      [token]
    );
    if (!sess.rows.length) return res.status(401).json({ success: false, error: 'Invalid session' });
    const codeId = sess.rows[0].id;
    const clientName = sess.rows[0].client_name;
    const pages = await pool.query(
      `SELECT * FROM client_progress WHERE code_id=$1 ORDER BY sort_order, id`,
      [codeId]
    );
    res.json({ success: true, client_name: clientName, pages: pages.rows });
  } catch (e) { res.status(500).json({ success: false, error: e.message }); }
});

