app.post('/api/content/research', verifyEngineAccess, requireCredits('research'), async (req, res) => {
  try {
    const { profile_id, seed_keyword, research_all } = req.body;
    if (!profile_id || !seed_keyword) return res.status(400).json({ success: false, error: 'profile_id and seed_keyword required' });
    const profileR = await pool.query(`SELECT cp.*, COALESCE(json_agg(cl ORDER BY cl.sort_order) FILTER (WHERE cl.id IS NOT NULL), '[]') AS locations FROM content_profiles cp LEFT JOIN content_locations cl ON cl.profile_id=cp.id WHERE cp.id=$1 GROUP BY cp.id`, [profile_id]);
    if (!profileR.rows.length) return res.status(404).json({ success: false, error: 'Profile not found' });
    const profile = profileR.rows[0];
    const geminiKey = process.env.GEMINI_API_KEY;
    if (!geminiKey) return res.status(500).json({ success: false, error: 'GEMINI_API_KEY not set' });

    // Step 1: Fetch sitemap links
    let sitemapLinks = [];
    if (profile.sitemap_url) {
      try {
        const sitemapResp = await fetch(profile.sitemap_url, { headers: { 'User-Agent': 'ContentScaleBot/1.0' }, signal: AbortSignal.timeout(8000) });
        const sitemapText = await sitemapResp.text();
        const urlMatches = sitemapText.match(/<loc>(.*?)<\/loc>/g) || [];
        sitemapLinks = urlMatches.map(m => m.replace(/<\/?loc>/g, '').trim()).filter(u => u.length > 0).slice(0, 100);
      } catch(e) { console.warn('Sitemap fetch failed:', e.message); }
    }

    // Step 2: Web search for top competitors
    const searchQuery = `${seed_keyword} ${profile.niche || ''} ${profile.geo_focus || ''}`.trim();
    let serpResults = [];
    try {
      const searchResp = await fetch(`https://www.googleapis.com/customsearch/v1?q=${encodeURIComponent(searchQuery)}&key=${process.env.GOOGLE_SEARCH_API_KEY}&cx=${process.env.GOOGLE_SEARCH_CX}&num=5`);
      if (searchResp.ok) {
        const searchData = await searchResp.json();
        serpResults = (searchData.items || []).map(item => ({ title: item.title, url: item.link, snippet: item.snippet }));
      }
    } catch(e) { console.warn('Search API failed:', e.message); }

    // Step 3: AI keyword + competitive research
    const locationsList = (profile.locations || []).map(l => `${l.location_type}: ${l.location_value}`).join(', ');
    const researchPrompt = `You are an expert SEO strategist. Analyze this seed keyword and business context, then return a complete research JSON.

BUSINESS CONTEXT:
- Business: ${profile.name}
- Domain: ${profile.domain}
- Niche: ${profile.niche}
- Target audience: ${profile.target_audience}
- Geo focus: ${locationsList || profile.geo_focus || 'Not specified'}
- Primary goal: ${profile.primary_goal}

SEED KEYWORD: "${seed_keyword}"

TOP 5 SERP RESULTS (current competitors):
${serpResults.map((r,i) => `${i+1}. ${r.title}\n   URL: ${r.url}\n   Snippet: ${r.snippet}`).join('\n\n')}

EXISTING SITE PAGES (for internal linking):
${sitemapLinks.slice(0,30).join('\n')}

Return ONLY valid JSON with this exact structure:
{
  "primary_keyword": "exact optimized primary keyword",
  "secondary_keywords": ["kw1","kw2","kw3","kw4","kw5"],
  "lsi_keywords": ["lsi1","lsi2","lsi3"],
  "long_tail_variants": ["variant1","variant2","variant3"],
  "search_intent": "BOFU|commercial|informational",
  "monthly_search_volume_estimate": "high|medium|low",
  "keyword_difficulty_estimate": "high|medium|low",
  "competitor_analysis": [
    {
      "url": "competitor url",
      "title": "their title",
      "strengths": "what they do well",
      "weaknesses": "gaps and weaknesses to exploit",
      "word_count_estimate": 1500,
      "has_faq": true,
      "has_local_signals": false
    }
  ],
  "content_gaps": ["gap1","gap2","gap3"],
  "ranking_opportunities": ["opportunity1","opportunity2"],
  "recommended_title": "Click-worthy SEO title that beats competitors",
  "title_alternatives": ["alt title 1","alt title 2"],
  "recommended_h2s": ["H2 section 1","H2 section 2","H2 section 3","H2 section 4","H2 section 5"],
  "target_word_count": 2000,
  "internal_links_suggested": ["url1","url2","url3"],
  "external_links_local": ["authoritative local source 1","authoritative local source 2"],
  "bofu_cta_suggestions": ["CTA 1","CTA 2"],
  "ai_overview_tips": ["tip to rank in AI overview 1","tip 2"]
}`;

    const gemResult = await callGeminiWithFallback(
      geminiKey,
      { contents: [{ parts: [{ text: researchPrompt }] }], generationConfig: { temperature: 0.3, maxOutputTokens: 4096, responseMimeType: 'application/json', thinkingConfig: { thinkingBudget: 0 } } }
    );
    const geminiData = gemResult.data;
    if (!gemResult.ok) {
      const apiErr = gemResult.errorMessage || `Gemini HTTP ${gemResult.status}`;
      console.error('Gemini research API error:', apiErr, geminiData);
      return res.status(502).json({ success: false, error: `Gemini API error: ${apiErr}`, model: gemResult.modelUsed });
    }
    const blockReason = geminiData?.promptFeedback?.blockReason;
    if (blockReason) return res.status(502).json({ success: false, error: `Gemini blocked the prompt: ${blockReason}` });
    const finishReason = geminiData?.candidates?.[0]?.finishReason;
    const rawText = geminiData?.candidates?.[0]?.content?.parts?.[0]?.text || '';
    if (!rawText) return res.status(502).json({ success: false, error: `Gemini returned no content (finishReason: ${finishReason || 'unknown'})`, model: gemResult.modelUsed });
    let keywordData;
    try {
      // Strip code fences if present, then try direct parse, then fallback to regex extraction
      const cleaned = rawText.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
      try {
        keywordData = JSON.parse(cleaned);
      } catch (_) {
        const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
        if (!jsonMatch) return res.status(502).json({ success: false, error: 'AI did not return JSON', raw_preview: rawText.slice(0, 300) });
        keywordData = JSON.parse(jsonMatch[0]);
      }
    } catch (parseErr) {
      console.error('Research JSON parse failed:', parseErr.message, 'raw:', rawText.slice(0, 500));
      return res.status(502).json({ success: false, error: `AI returned invalid JSON: ${parseErr.message}`, raw_preview: rawText.slice(0, 300) });
    }

    // Save job
    const jobR = await pool.query(
      `INSERT INTO content_jobs (profile_id, seed_keyword, status, keyword_data, competitor_data, sitemap_links) VALUES ($1,$2,'researched',$3,$4,$5) RETURNING *`,
      [profile_id, seed_keyword, JSON.stringify(keywordData), JSON.stringify(keywordData.competitor_analysis || []), JSON.stringify(sitemapLinks)]
    );

    // If research_all: do a second AI pass to research full keyword universe
    let allKeywordData = null;
    if (research_all) {
      const allKwPrompt = `You are an expert SEO keyword researcher. Given the seed keyword and initial research, build a complete keyword universe.

SEED KEYWORD: "${seed_keyword}"
BUSINESS: ${profile.name} — ${profile.niche}
INITIAL KEYWORDS FOUND: ${[...(keywordData.secondary_keywords||[]), ...(keywordData.lsi_keywords||[]), ...(keywordData.long_tail_variants||[])].join(', ')}
CONTENT GAPS: ${(keywordData.content_gaps||[]).join(', ')}

Analyze ALL keyword opportunities: secondary, long-tail, local variants, question-based, commercial intent, BOFU.
Return ONLY valid JSON:
{
  "total_keywords_analyzed": 25,
  "top_opportunities": ["kw1","kw2","kw3","kw4","kw5"],
  "quick_wins": ["low competition kw1","low competition kw2","low competition kw3"],
  "long_tail_goldmine": ["long tail 1","long tail 2","long tail 3","long tail 4"],
  "question_keywords": ["how to...","what is...","best...","cost of..."],
  "local_variants": ["keyword + city","keyword + province"],
  "bofu_keywords": ["buy","hire","cost","price","near me variants"],
  "content_ideas": ["title idea 1","title idea 2","title idea 3","title idea 4","title idea 5"],
  "priority_order": ["first write this","then this","then this"]
}`;

      try {
        const allKwResult = await callGeminiWithFallback(
          geminiKey,
          { contents: [{ parts: [{ text: allKwPrompt }] }], generationConfig: { temperature: 0.3, maxOutputTokens: 2048, responseMimeType: 'application/json', thinkingConfig: { thinkingBudget: 0 } } }
        );
        const allKwData = allKwResult.data;
        const allKwText = allKwData?.candidates?.[0]?.content?.parts?.[0]?.text || '';
        if (allKwText) {
          const cleaned = allKwText.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
          try {
            allKeywordData = JSON.parse(cleaned);
          } catch (_) {
            const allKwMatch = cleaned.match(/\{[\s\S]*\}/);
            if (allKwMatch) allKeywordData = JSON.parse(allKwMatch[0]);
          }
          if (allKeywordData) {
            // Save back into job
            const merged = Object.assign({}, keywordData, { all_keyword_data: allKeywordData, all_keywords_researched: allKeywordData.total_keywords_analyzed });
            await pool.query(`UPDATE content_jobs SET keyword_data=$1, updated_at=NOW() WHERE id=$2`, [JSON.stringify(merged), jobR.rows[0].id]);
            keywordData.all_keyword_data = allKeywordData;
            keywordData.all_keywords_researched = allKeywordData.total_keywords_analyzed;
          }
        }
      } catch(e) { console.warn('Research all keywords failed:', e.message); }
    }

    res.json({ success: true, job: jobR.rows[0], research: keywordData });
  } catch(e) {
    console.error('Research error:', e);
    const msg = e.code ? `${e.message} (db code ${e.code})` : e.message;
    res.status(500).json({ success: false, error: msg, where: 'research' });
  }
});

// ── Generate Brief ───────────────────────────────────────────
app.post('/api/content/brief/:jobId', verifyEngineAccess, requireCredits('brief'), async (req, res) => {
  try {
    const jobR = await pool.query(`SELECT j.*, cp.* FROM content_jobs j JOIN content_profiles cp ON cp.id=j.profile_id WHERE j.id=$1`, [req.params.jobId]);
    if (!jobR.rows.length) return res.status(404).json({ success: false, error: 'Job not found' });
    const job = jobR.rows[0];
    const kd = job.keyword_data;
    const locations = await pool.query(`SELECT * FROM content_locations WHERE profile_id=$1 ORDER BY sort_order`, [job.profile_id]);
    const locList = locations.rows.map(l => `${l.location_type}: ${l.location_value} (external links: ${l.external_links})`).join('\n');

    const brief = {
      title: kd.recommended_title,
      title_alternatives: kd.title_alternatives,
      primary_keyword: kd.primary_keyword,
      secondary_keywords: kd.secondary_keywords,
      lsi_keywords: kd.lsi_keywords,
      search_intent: kd.search_intent,
      target_word_count: kd.target_word_count || 2000,
      structure: kd.recommended_h2s,
      internal_links: (kd.internal_links_suggested || []).slice(0,5),
      external_links_local: kd.external_links_local || [],
      bofu_ctas: kd.bofu_cta_suggestions || [],
      ai_overview_tips: kd.ai_overview_tips || [],
      content_gaps_to_fill: kd.content_gaps || [],
      competitor_weaknesses: (kd.competitor_analysis || []).map(c => c.weaknesses),
      locations: locList
    };

    await pool.query(`UPDATE content_jobs SET brief=$1, status='briefed', updated_at=NOW() WHERE id=$2`, [JSON.stringify(brief), req.params.jobId]);
    res.json({ success: true, brief });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

// ── Write Article ────────────────────────────────────────────
app.post('/api/content/write/:jobId', verifyEngineAccess, requireCredits('write'), async (req, res) => {
  // Helper: parse a value that might be a JS object already (jsonb) or a JSON string (text column), safely
  const safeParse = (v, fallback) => {
    if (v == null) return fallback;
    if (typeof v !== 'string') return v;
    try { return JSON.parse(v); } catch (_) { return fallback; }
  };
  try {
    const { title_override } = req.body;
    const jobR = await pool.query(
      `SELECT j.*, cp.name as profile_name, cp.domain, cp.niche, cp.target_audience, cp.primary_goal, cp.html_template, cp.wp_url
       FROM content_jobs j JOIN content_profiles cp ON cp.id=j.profile_id WHERE j.id=$1`,
      [req.params.jobId]
    );
    if (!jobR.rows.length) return res.status(404).json({ success: false, error: 'Job not found' });
    const job = jobR.rows[0];
    const brief = safeParse(job.brief, null);
    const kd = safeParse(job.keyword_data, {});
    if (!brief) return res.status(400).json({ success: false, error: 'Generate brief first' });

    const geminiKey = process.env.GEMINI_API_KEY;
    if (!geminiKey) return res.status(500).json({ success: false, error: 'GEMINI_API_KEY not set' });
    const title = title_override || brief.title;
    const locations = await pool.query(`SELECT * FROM content_locations WHERE profile_id=$1 AND external_links=TRUE ORDER BY sort_order`, [job.profile_id]);
    const locStrings = locations.rows.map(l => `${l.location_type}: ${l.location_value}`).join(', ');

    const internalLinksStr = (brief.internal_links || []).map(u => `- ${u}`).join('\n');
    const h2Structure = (brief.structure || []).map((h,i) => `H2 ${i+1}: ${h}`).join('\n');

    // GSC from saved job
    const gsc = brief.gsc || safeParse(job.gsc_data, {}) || {};
    const gscQueries = (gsc.queries||[]).filter(Boolean);
    const gscBlock = (gscQueries.length || gsc.impressions) ? `
GSC DATA:
Impressions: ${gsc.impressions||'—'} | Clicks: ${gsc.clicks||'—'} | Positie: ${gsc.position||'—'} | CTR: ${gsc.ctr||'—'}%
Rankende pagina's: ${(gsc.pages||[]).join(', ')||'—'}
Echte zoekopdrachten (verwerk in headings en body): ${gscQueries.join(', ')}
` : '';

    // Verified business facts — no hallucinations
    const bi = safeParse(job.business_info, {}) || {};
    const verifiedFacts = [
      bi.phone         ? `- Telefoon: ${bi.phone}` : null,
      bi.email         ? `- Email: ${bi.email}` : null,
      bi.address       ? `- Adres: ${bi.address}${bi.city ? ', '+bi.city : ''}` : null,
      bi.kvk           ? `- KvK: ${bi.kvk}` : null,
      bi.btw           ? `- BTW: ${bi.btw}` : null,
      bi.founded_year  ? `- Opgericht: ${bi.founded_year}` : null,
      bi.owner_name    ? `- Eigenaar: ${bi.owner_name}` : null,
      bi.review_score  ? `- Reviews: ${bi.review_score} (${bi.review_count||''} op ${bi.review_platform||''})` : null,
      bi.opening_hours ? `- Openingstijden: ${bi.opening_hours}` : null,
      (bi.certifications||[]).length ? `- Certificaten: ${bi.certifications.join(', ')}` : null,
      (bi.unique_selling_points||[]).length ? `- USPs: ${bi.unique_selling_points.join(' | ')}` : null,
    ].filter(Boolean).join('\n');

    const antiFacts = verifiedFacts
      ? `GEBRUIK ALLEEN DEZE GEGEVENS. Verzin NOOIT telefoonnummers, adressen, e-mails of andere contactgegevens die niet hierboven staan. Ontbrekende gegevens = weglaten of [CONTACT] gebruiken.`
      : `Er zijn geen bedrijfsgegevens gescrapt. Verzin GEEN telefoonnummers, adressen, e-mails of andere contactgegevens. Gebruik [CONTACT] als placeholder.`;

    // Real internal links from sitemap only
    const realLinks = (brief.internal_links || brief.sitemap_all || [])
      .filter(u => typeof u === 'string' && u.length > 10).slice(0, 30);
    const internalLinksBlock = realLinks.length
      ? `Gebruik ALLEEN deze exacte URLs van de sitemap — verzin er GEEN:\n${realLinks.map(u=>`- ${u}`).join('\n')}`
      : 'Geen sitemap-URLs beschikbaar — voeg GEEN interne links toe.';

    // Build JSON-LD schema from verified data
    const schemaType = bi.schema_type || 'LocalBusiness';
    const schemaObj = { '@context':'https://schema.org','@type':schemaType,'name':bi.business_name||job.profile_name,'url':job.domain?(job.domain.startsWith('http')?job.domain:'https://'+job.domain):undefined };
    if (bi.phone)   schemaObj['telephone'] = bi.phone;
    if (bi.email)   schemaObj['email'] = bi.email;
    if (bi.address) schemaObj['address'] = {'@type':'PostalAddress','streetAddress':bi.address,'addressLocality':bi.city,'addressCountry':bi.country};
    if (bi.opening_hours) schemaObj['openingHours'] = bi.opening_hours;
    if (bi.review_score)  schemaObj['aggregateRating'] = {'@type':'AggregateRating','ratingValue':bi.review_score,'reviewCount':bi.review_count||undefined};
    if ((bi.service_areas||[]).length) schemaObj['areaServed'] = bi.service_areas;

    // ── Two completely different prompts depending on whether a template exists ──
        // Research complete — brief saved, job updated
    // NOTE: HTML content generation moved to /api/content/write/:jobId (Claude)
    await pool.query(`UPDATE content_jobs SET status='completed', result_data=$1, completed_at=NOW() WHERE id=$2`, [JSON.stringify(brief), jobId]);

    res.json({ success: true, brief, jobId: job.id, message: 'Research complete. Use Writer to generate HTML content.' });
  } catch(e) {
    console.error('Write error:', e);
    const msg = e.code ? `${e.message} (db code ${e.code})` : e.message;
    res.status(500).json({ success: false, error: msg, where: 'write' });
  }
});

