// ── WordPress Publish ────────────────────────────────────────
app.post('/api/content/articles/:id/publish-wp', verifyEngineAccess, async (req, res) => {
  try {
    const articleR = await pool.query(
      `SELECT a.*, cp.wp_url, cp.wp_user, cp.wp_app_password FROM content_articles a JOIN content_profiles cp ON cp.id=a.profile_id WHERE a.id=$1`,
      [req.params.id]
    );
    if (!articleR.rows.length) return res.status(404).json({ success: false, error: 'Article not found' });
    const article = articleR.rows[0];
    if (!article.wp_url || !article.wp_user || !article.wp_app_password) return res.status(400).json({ success: false, error: 'WordPress credentials not configured for this profile' });
    const wpApiUrl = article.wp_url.replace(/\/$/, '') + '/wp-json/wp/v2/posts';
    const credentials = Buffer.from(`${article.wp_user}:${article.wp_app_password}`).toString('base64');
    const wpResp = await fetch(wpApiUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Basic ${credentials}` },
      body: JSON.stringify({ title: article.title, content: article.html_content, slug: article.slug, status: 'draft' })
    });
    if (!wpResp.ok) {
      const err = await wpResp.text();
      return res.status(400).json({ success: false, error: `WordPress error: ${err.substring(0,200)}` });
    }
    const wpData = await wpResp.json();
    await pool.query(`UPDATE content_articles SET wp_post_id=$1, wp_url=$2, status='published', published_at=NOW(), updated_at=NOW() WHERE id=$3`,
      [wpData.id, wpData.link, article.id]);
    res.json({ success: true, wp_post_id: wpData.id, wp_url: wpData.link });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

